using System.Text.Encodings.Web;
using Common.Security.Hosting;
using Common.Security.Models;
using Common.Secrets;
using Microsoft.Data.Sqlite;
internal static class SuiteSecurityExtensions{
static bool SafeLocal(string value)=>!string.IsNullOrWhiteSpace(value)&&value.StartsWith('/')&&!value.StartsWith("//",StringComparison.Ordinal)&&!value.Contains("\\",StringComparison.Ordinal);public static IServiceCollection AddSuiteSecurity(this IServiceCollection services, IConfiguration configuration, IHostEnvironment environment)
    {
        var definition = new SuiteApplication("Aegis.Configuration", "Aegis.Configuration.Session", new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase)
        {
            ["Administrator"] = ["Configuration.View","Configuration.Manage","Security.Manage"],
            ["Operator"] = ["Configuration.View","Configuration.Manage"],
            ["Reader"] = ["Configuration.View"],
            ["Diagnostics"] = ["Diagnostics.View","Diagnostics.Run"]
        });
        return services.AddCommonSuiteSecurity(definition, provider =>
        {
            string? path = configuration["SuiteSecurity:AccountStorePath"];
            if (string.IsNullOrWhiteSpace(path))
            {
                if (!environment.IsDevelopment()) throw new InvalidOperationException("SuiteSecurity:AccountStorePath must point to the same protected identity database for all Control Plane applications.");
                path = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Aegis", "ControlPlane", "security.db");
            }
            Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);
            return new SqliteConnection(new SqliteConnectionStringBuilder { DataSource = path, ForeignKeys = true }.ToString());
        }, configuration.GetValue("SuiteSecurity:Entra:Enabled", false) ? provider => SuiteSecurityRegistration.EntraOptions(
            configuration, provider.GetRequiredService<ISecretProvider>().GetRequiredAsync("SuiteSecurity:Entra:ClientSecret").GetAwaiter().GetResult()) : null);
    }private const string OperationsSso="https://operations.ffpja.org/handoff/configuration";static string SsoUrl(string destination)=>OperationsSso+"?returnUrl="+Uri.EscapeDataString(SafeLocal(destination)?destination:"/");public static void UseSuiteSecurity(this WebApplication app){app.Use(async(ctx,next)=>{string lifecyclePath=ctx.Request.Path.Value??string.Empty;bool publicLifecycle=lifecyclePath.Equals("/api/registration/request",StringComparison.OrdinalIgnoreCase)||lifecyclePath.Equals("/api/registration/authenticate",StringComparison.OrdinalIgnoreCase)||lifecyclePath.Equals("/api/registration/recovery",StringComparison.OrdinalIgnoreCase)||(lifecyclePath.StartsWith("/api/registration/",StringComparison.OrdinalIgnoreCase)&&lifecyclePath.EndsWith("/claim",StringComparison.OrdinalIgnoreCase));bool machineRegistrationRead=lifecyclePath.Equals("/api/registration/flow",StringComparison.OrdinalIgnoreCase)&&ctx.Request.Headers.ContainsKey("X-Aegis-Registration-Key")&&ctx.Request.Headers.ContainsKey("X-Aegis-Application-Id")&&ctx.Request.Headers.ContainsKey("X-Aegis-Instance-Id");if(ctx.Request.Path.StartsWithSegments("/health")||ctx.Request.Path.StartsWithSegments("/login")||ctx.Request.Path.StartsWithSegments("/auth")||publicLifecycle||machineRegistrationRead||ctx.Request.Path.Equals("/api/contracts/register",StringComparison.OrdinalIgnoreCase)||ctx.Request.Path.Equals("/api/contracts/discovery",StringComparison.OrdinalIgnoreCase)||ctx.Request.Path.StartsWithSegments("/api/contracts/reconcile")||ctx.Request.Path.StartsWithSegments("/api/contracts/")){await next();return;}var s=ctx.RequestServices.GetRequiredService<SuiteSecurity>();var identity=s.Read(ctx.Request);if(identity is null){if(ctx.Request.Path.StartsWithSegments("/api")){ctx.Response.StatusCode=StatusCodes.Status401Unauthorized;return;}ctx.Response.Redirect(SsoUrl(ctx.Request.Path+ctx.Request.QueryString));return;}ctx.Items["SuiteIdentity"]=identity;await s.SignInAsync(ctx,identity);await next();});}public static void MapSuiteSecurity(this WebApplication app){app.MapGet("/login",(string? returnUrl)=>Results.Redirect(SsoUrl(returnUrl??"/")));app.MapPost("/auth/login",async(HttpContext x,SuiteSecurity s,ILogger<SuiteSecurity> logger)=>{var f=await x.Request.ReadFormAsync();string u=f["username"].ToString();string r=f["returnUrl"].ToString();try{var i=s.Authenticate(u,f["password"].ToString());if(i is null)return Results.Redirect("/login?error=1");await s.SignInAsync(x,i);return Results.Redirect(SafeLocal(r)?r:"/");}catch(Exception ex){logger.LogError(ex,"Configuration authentication backend failed for user {UserName}.",u);return Results.Redirect("/login?error=backend");}}).RequireRateLimiting(AccountSecurityHosting.LoginRateLimit);app.MapPost("/auth/handoff",async(HttpContext x,SuiteSecurity s)=>{var f=await x.Request.ReadFormAsync();string token=f["token"].ToString();var i=s.AcceptHandoff(token);if(i is null)return Results.Redirect("/login?error=handoff");await s.SignInAsync(x,i);x.Response.Headers.CacheControl="no-store";string r=f["returnUrl"].ToString();return Results.Redirect(SafeLocal(r)?r:"/");});app.MapGet("/auth/me",async(HttpContext x,SuiteSecurity s)=>{var i=s.Read(x.Request);if(i is null)return Results.Unauthorized();await s.SignInAsync(x,i);return Results.Ok(new { i.UserName, i.DisplayName, i.Title, i.Permissions, clientIp=x.Connection.RemoteIpAddress?.ToString() ?? "unknown", idleTimeoutMinutes=s.IdleTimeoutMinutes });});app.MapGet("/auth/logout",async(HttpContext x,SuiteSecurity s)=>{await s.SignOutAsync(x);return Results.Redirect("/login");});}}
